const USER_AGENT = "net.umanle.arca.android.playstore/0.9.75";
const TARGETS = [
  ["all", "전체"],
  ["title_content", "제목/내용"],
  ["title", "제목"],
  ["content", "내용"],
  ["nickname", "글쓴이"]
];

const select = (e, t, r) => ({
  type_name: "SelectFilter",
  type: e,
  name: t,
  state: 0,
  values: r.map(([e, t]) => ({ type_name: "SelectOption", name: t, value: e }))
});

const flattenFilters = (raw) => {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  if (typeof raw === "object") return Object.values(raw);
  return [];
};

const chosen = (e, t) => {
  const list = flattenFilters(e);
  const r = list.find((item) => item && (item.type === t || item.name === t));
  if (!r) return "";

  const vals = Array.isArray(r.values) ? r.values : [];
  const rawState = r.state !== undefined && r.state !== null ? r.state : r.value;

  if (rawState && typeof rawState === "object") {
    if ("value" in rawState) return String(rawState.value ?? "");
    if ("name" in rawState && vals.length) {
      const foundByName = vals.find((v) => v && typeof v === "object" && v.name === rawState.name);
      if (foundByName && "value" in foundByName) return String(foundByName.value ?? "");
    }
  }

  if (vals.length) {
    const idx = Number(rawState);
    if (Number.isInteger(idx) && idx >= 0 && idx < vals.length) {
      const opt = vals[idx];
      if (opt && typeof opt === "object" && "value" in opt) return String(opt.value ?? "");
      return String(opt ?? "");
    }
    if (typeof rawState === "string" && rawState !== "") {
      const found = vals.find((v) =>
        v && typeof v === "object" ? (String(v.value) === rawState || String(v.name) === rawState) : String(v) === rawState
      );
      if (found) {
        return typeof found === "object" && "value" in found ? String(found.value ?? "") : String(found);
      }
    }
  }

  return rawState !== undefined && rawState !== null ? String(rawState) : "";
};

const https = (e) => String(e || "").replace(/^\/\//, "https://");

const encodeCategory = (cat) => {
  const raw = String(cat || "");
  if (!raw) return "";
  try {
    return encodeURIComponent(decodeURIComponent(raw));
  } catch (e) {
    return encodeURIComponent(raw);
  }
};

class DefaultExtension extends MProvider {
  constructor() {
    super();
    this._memPref = {};
  }

  get supportsLatest() {
    return true;
  }

  get sourceKey() {
    return String(this.source?.id || "48102741");
  }

  pref(e) {
    try {
      const sp = new SharedPreferences();
      let val;
      if (typeof sp.getString === "function") {
        val = sp.getString(e, "");
      }
      if ((val === null || val === undefined || val === "") && typeof sp.get === "function") {
        val = sp.get(e);
      }
      if (val !== null && val !== undefined && String(val).trim() !== "") {
        return String(val).trim();
      }
    } catch (e) {}
    return Object.prototype.hasOwnProperty.call(this._memPref, e) ? String(this._memPref[e] ?? "").trim() : "";
  }

  setPref(e, val) {
    const str = String(val ?? "");
    this._memPref[e] = str;
    try {
      const sp = new SharedPreferences();
      if (typeof sp.setString === "function") {
        sp.setString(e, str);
      }
      if (typeof sp.set === "function") {
        sp.set(e, str);
      }
    } catch (e) {}
  }

  _decodeSavedCat(raw, fallback) {
    if (raw === undefined || raw === null || raw === "") return fallback;
    if (raw === "__ALL__") return "";
    return raw;
  }

  _encodeSavedCat(cat) {
    return cat === "" ? "__ALL__" : String(cat);
  }

  get params() {
    const sourceId = Number(this.source?.id);

    const idMappings = {
      48102741: {
        board: "lovelove",
        category: "",
        popularCategory: "(야하다)",
        categories: [
          ["", "전체"],
          ["창작물", "창작물"],
          ["창작물(야하다)", "창작물 19"],
          ["(건전)", "건전"],
          ["(건전-시리즈)", "건전-시리즈"],
          ["(야하다)", "19"],
          ["취향", "취향"],
          ["취-시리즈", "취향- 시리즈"],
          ["취향(야하다)", "취향 19"],
          ["2차창작", "2차 창작"],
          ["2차%20🔞", "2차 19"]
        ]
      },
      48102742: {
        board: "lily",
        category: "",
        popularCategory: "",
        categories: [
          ["", "전체"],
          ["짤", "짤"],
          ["번역", "번역"],
          ["19핫산", "19핫산"],
          ["19창작", "19창작"],
          ["19", "19"],
          ["만화", "만화"],
          ["Ai", "Ai"],
          ["Ai19", "Ai19"]
        ]
      },
      48102744: {
        board: "yazzal",
        category: "",
        popularCategory: "",
        categories: [
          ["", "전체"],
          ["은꼴", "은꼴"],
          ["R-18", "R-18"],
          ["페도", "로리"],
          ["기타", "기타 이상성욕"],
          ["실사은꼴", "실사은꼴(야짤x"],
          ["창작", "창작"],
          ["AI그림", "AI그림"],
          ["만화", "동인지/망가"]
        ]
      },
      48102746: {
        board: "404notfound",
        category: "",
        popularCategory: "",
        categories: [
          ["", "전체"],
          ["3", "창작"],
          ["5", "야짤"]
        ]
      },
      48102747: { board: "", category: "", popularCategory: "", categories: [] },
      48102748: { board: "", category: "", popularCategory: "", categories: [] },
      48102749: { board: "", category: "", popularCategory: "", categories: [] }
    };

    const mapped = idMappings[sourceId] || {
      board: "lovelove",
      category: "",
      popularCategory: "",
      categories: []
    };

    const board = mapped.board && mapped.board !== "" ? mapped.board : "lovelove";
    const defaultCat = mapped.category !== undefined ? String(mapped.category) : "";
    const defaultPopCat = mapped.popularCategory !== undefined ? String(mapped.popularCategory) : "";

    const category = this._decodeSavedCat(this.pref(`category_${this.sourceKey}`), defaultCat);
    const popularCategory = this._decodeSavedCat(this.pref(`popularCategory_${this.sourceKey}`), defaultPopCat);

    const savedPopMode = this.pref(`popularBest_${this.sourceKey}`);
    const popularBest = savedPopMode === "0" ? false : true;

    const savedLatestMode = this.pref(`latestBest_${this.sourceKey}`);
    const latestBest = savedLatestMode === "1" ? true : false;

    const categories = Array.isArray(mapped.categories) ? mapped.categories : [];

    return { board, category, popularCategory, popularBest, latestBest, categories };
  }

  get board() {
    const { board: e } = this.params;
    if (!e || !/^[A-Za-z0-9_-]+$/.test(e)) {
      throw new Error("올바른 아카라이브 채널 ID가 아닙니다.");
    }
    return e;
  }

  _categoryLabel(catValue) {
    const found = (this.params.categories || []).find(([id]) => String(id) === String(catValue));
    return found ? found[1] : (catValue || "전체");
  }

  getHeaders() {
    return {
      "User-Agent": USER_AGENT,
      "X-Device-Token": this._token || (this._token = Array.from({ length: 64 }, () => Math.floor(16 * Math.random()).toString(16)).join(""))
    };
  }

  post(e) {
    const t = /^(?:https:\/\/arca\.live)?\/b\/([A-Za-z0-9_-]+)\/(\d+)(?:[?#]|$)/.exec(String(e));
    if (!t) throw new Error("아카라이브 게시글 주소가 아닙니다.");
    return { board: t[1], id: t[2] };
  }

  async api(e) {
    const t = this._client || (this._client = new Client({ timeout: 20, connectTimeout: 8 })),
      r = await t.get(`${this.source.baseUrl}/api/app${e}`, this.getHeaders());
    if (/<title>\s*Just a moment|id=["']cf-chl/i.test(r.body))
      throw new Error("WebView에서 사이트 인증을 완료한 후 다시 시도해 주세요.");
    let a;
    try {
      a = JSON.parse(r.body);
    } catch (e) {
      throw new Error(`아카라이브 응답을 읽을 수 없습니다 (HTTP ${r.statusCode}).`);
    }
    if (200 !== r.statusCode || !1 === a.result)
      throw new Error(`아카라이브: ${a.message || `HTTP ${r.statusCode}`}`);
    return a;
  }

  async list(e, { best: t = !1, query: r = "", target: a = "all", filters: filters = null } = {}, fixedCategory = null) {
    if (!Number.isSafeInteger(e) || e < 1) throw new Error("올바른 페이지 번호가 아닙니다.");

    const s = this.board;
    const defaultCat = t ? this.params.popularCategory : this.params.category;
    const selectedCat = fixedCategory !== null
      ? fixedCategory
      : (filters && this.params.categories.length ? chosen(filters, "category") : defaultCat);

    let notice = "";
    if (fixedCategory === null && e === 1 && filters) {
      const action = chosen(filters, "tabSave") || "0";
      const label = this._categoryLabel(selectedCat);
      const modeLabel = t ? "인기(개념글)" : "최신(전체글)";

      if (action === "1") {
        this.setPref(`popularCategory_${this.sourceKey}`, this._encodeSavedCat(selectedCat));
        this.setPref(`popularBest_${this.sourceKey}`, t ? "1" : "0");
        notice = `[인기 탭 저장] ${label} · ${modeLabel}`;
      } else if (action === "2") {
        this.setPref(`category_${this.sourceKey}`, this._encodeSavedCat(selectedCat));
        this.setPref(`latestBest_${this.sourceKey}`, t ? "1" : "0");
        notice = `[최신 탭 저장] ${label} · ${modeLabel}`;
      } else if (action === "3") {
        this.setPref(`popularCategory_${this.sourceKey}`, "");
        this.setPref(`popularBest_${this.sourceKey}`, "");
        notice = `[인기 탭 기본값 복원]`;
      } else if (action === "4") {
        this.setPref(`category_${this.sourceKey}`, "");
        this.setPref(`latestBest_${this.sourceKey}`, "");
        notice = `[최신 탭 기본값 복원]`;
      } else if (action === "5") {
        this.setPref(`popularCategory_${this.sourceKey}`, "");
        this.setPref(`popularBest_${this.sourceKey}`, "");
        this.setPref(`category_${this.sourceKey}`, "");
        this.setPref(`latestBest_${this.sourceKey}`, "");
        notice = `[모두 기본값 복원]`;
      } else if (!r.trim()) {
        this.setPref(`latestBest_${this.sourceKey}`, t ? "1" : "0");
      }
    }

    const n = [`p=${e}`];
    if (selectedCat) n.push(`category=${encodeCategory(selectedCat)}`);
    if (t) n.push("mode=best");
    if (r.trim()) n.push(`target=${encodeURIComponent(a)}`, `keyword=${encodeURIComponent(r.trim().slice(0, 128))}`);

    const { articles: o = [], next: l } = await this.api(`/list/channel/${s}?${n.join("&")}`);

    const map = new Map();
    if (notice) {
      map.set("__notice__", {
        name: notice,
        link: `/b/${s}/0`,
        imageUrl: ""
      });
    }

    for (const item of o) {
      if (item.id && item.title) {
        const link = `/b/${s}/${item.id}`;
        if (!map.has(link)) {
          map.set(link, {
            name: String(item.title).trim(),
            link: link,
            imageUrl: https(item.thumbnailUrl)
          });
        }
      }
    }
    const c = [...map.values()];
    const hasNext = c.length > 0 && (Boolean(l) || o.length > 0);

    return { list: c, hasNextPage: hasNext };
  }

  getPopular(e) {
    return this.list(e, { best: this.params.popularBest }, this.params.popularCategory);
  }

  getLatestUpdates(e) {
    return this.list(e, { best: this.params.latestBest }, this.params.category);
  }

  search(e, t, r) {
    const modeVal = chosen(r, "mode");
    return this.list(t, {
      best: modeVal === "best",
      query: String(e || ""),
      target: chosen(r, "target") || "all",
      filters: r
    }, null);
  }

  getFilterList() {
    const list = [
      select("mode", "목록", [["", "최신 (전체글)"], ["best", "인기 (개념글)"]]),
      select("target", "검색 대상", TARGETS)
    ];
    const cats = this.params.categories || [];
    if (cats.length) {
      list.push(select("category", "카테고리", cats));
      list.push(
        select("tabSave", "인기/최신 탭 저장", [
          ["0", "저장하지 않음"],
          ["1", "선택한 탭을 인기 탭에 저장"],
          ["2", "선택한 탭을 최신 탭에 저장"],
          ["3", "인기 탭 기본값 복원"],
          ["4", "최신 탭 기본값 복원"],
          ["5", "두 탭 모두 기본값 복원"]
        ])
      );
    }
    return list;
  }

  async article(e) {
    const { board: t, id: r } = this.post(e),
      a = await this.api(`/view/article/${t}/${r}`);
    return {
      data: a,
      link: `/b/${t}/${r}`,
      images: [...new Set((a.images || []).map(https).filter((e) => /^https:\/\/[^\s"'<>\\]+$/.test(e)))]
    };
  }

  async getDetail(e) {
    const { data: t, link: r, images: a } = await this.article(e),
      s = String(t.title || "").trim();
    if (!s) throw new Error("게시글을 찾을 수 없습니다. 삭제 또는 접근 제한 여부를 확인해 주세요.");
    const i = Date.parse(t.createdAt || "");
    return {
      name: s,
      link: r,
      imageUrl: a[0] || "",
      status: 1,
      author: String(t.nickname || "").trim(),
      genre: t.categoryDisplayName ? [String(t.categoryDisplayName)] : [],
      description: String(t.content || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim().slice(0, 500),
      chapters: [{ name: "본문", url: r, dateUpload: Number.isFinite(i) ? String(i) : null }]
    };
  }

  async getPageList(e) {
    const { images: t } = await this.article(e);
    if (!t.length) throw new Error("게시글 본문에 표시할 이미지가 없습니다.");
    return t.map((e) => ({ url: e, headers: { "User-Agent": USER_AGENT } }));
  }
}
